import {Session} from './core/protocol.mjs';
import {Device} from './core/device.mjs';
import {OfflineDevice} from './adapters/offline.mjs';
import {ports,openMidi} from './adapters/web-midi.mjs';
import {P,ROLE,NOTES,TONE,copy,rest,motif,grow,noteName,parseNotes,phraseFile,readPhrase} from './core/music.mjs';
const $=id=>document.getElementById(id);
const el=(tag,text,props={})=>{const n=document.createElement(tag);if(text!==null)n.textContent=text;Object.assign(n,props);return n;};
let data,dev,live=false,busy=false,midi,session,track=0,page=0,selectedStep=0,recovery=null;
const colors=['#c9b0ff','#f6a6d8','#a6f5d0','#f7ce87'],labels=['','','',''];
const friendly={0:'Level',1:'Attack',2:'Decay',3:'Sustain',4:'Release',9:'LFO speed',10:'LFO shape',14:'Filter movement',25:'Root',26:'Scale',27:'Quantise',28:'Transpose',29:'Sequence length',30:'Step division',31:'Swing',32:'Gate',33:'Distortion',34:'Chorus send',35:'Delay send',36:'Reverb send',37:'Voice mode',38:'Glide',39:'Pan',40:'Mute',95:'Stereo spread',103:'Evolution',104:'Mutation chance %',105:'Every N loops'};
function say(s,error=false){$('status').textContent=s;$('status').classList.toggle('error',error);}
function uiState(){const ready=!!dev&&(!live||!session?.closed);$('work').disabled=busy||!ready;$('find').disabled=busy||live;$('connect').disabled=busy||live||!midi;$('disconnect').disabled=busy||!live;$('offline').disabled=busy;$('mode').textContent=live?(session?.closed?'DISCONNECTED':'FM-1 / USB'):'OFFLINE / SILENT';$('recovery').disabled=busy||!recovery;}
async function run(fn,message='Updated.'){if(busy)return;busy=true;uiState();try{await fn();say(message);}catch(e){say(e.message,true);console.error(e);}finally{if(dev?.undo)recovery=copy(dev.undo.before);busy=false;if(dev)render();uiState();}}
function options(select,items,selected=0){select.replaceChildren(...items.map((x,i)=>{const o=el('option',typeof x==='string'?x:x.label,{value:String(typeof x==='string'?i:x.value)});return o;}));select.value=String(selected);}
function control(container,d,value,onchange,label){if(!d||d.max<=d.min||d.label==='-')return;const l=el('label',null),top=el('span',label||d.label),out=el('output','');top.append(out);l.append(top);let input;
 if(d.fmt===8){input=el('select',null);options(input,Array.from({length:d.max-d.min+1},(_,i)=>({value:d.min+i,label:d.names?.[i]??String(d.min+i)})),value);}else{input=el('input',null,{type:'range',min:String(d.min),max:String(d.max),step:'1',value:String(value)});}
 const display=v=>{out.value=d.fmt===8?'':d.fmt===10?NOTES[v%12]:String(v);};display(value);input.setAttribute('aria-label',label||d.label);input.addEventListener('input',()=>display(Number(input.value)));input.addEventListener('change',()=>run(()=>onchange(Number(input.value)),live?'FM-1 confirmed the value.':'Offline sketch updated.'));l.append(input);container.append(l);}
function controls(id,ids){const c=$(id);c.replaceChildren();for(const i of ids)control(c,dev.descs[track][i],dev.tracks[track].p[i],v=>dev.set(track,i,v),friendly[i]);}
function render(){const t=dev.tracks[track];document.documentElement.style.setProperty('--accent',colors[track]);$('tracks').replaceChildren(...dev.tracks.map((x,k)=>{const b=el('button',null,{className:'track'});b.style.setProperty('--track',colors[k]);b.setAttribute('aria-pressed',String(k===track));b.append(el('b',`0${k+1} / ${ROLE[k]}`),el('span',`${data.ENG[x.engine].name} · ${x.p[P.mute]?'MUTED':NOTES[x.p[P.root]]+' / '+data.scales[x.p[P.scale]].name}`));b.onclick=()=>{track=k;page=0;selectedStep=0;render();};return b;}));
 $('trackNum').textContent=`0${track+1} / ${ROLE[track]}`;$('soundName').textContent=labels[track]||`${data.ENG[t.engine].name} · ${data.ENG[t.engine].presets[t.preset]?.name||'Edited sound'}`;
 options($('sound'),data.library.banks[track].map(x=>x[0]));options($('root'),NOTES,t.p[P.root]);options($('scale'),data.scales.map(s=>s.name),t.p[P.scale]);options($('motif'),data.library.motifs.map(x=>x[0]));options($('engine'),data.ORDER.map(name=>({value:data.ENG.findIndex(e=>e.name===name),label:name})),t.engine);presetOptions(t.preset);
 controls('soundControls',[P.level,106+TONE[t.engine],P.attack,P.release,P.chorus,P.delay,P.reverb,P.pan]);
 controls('deepControls',[...Array.from({length:8},(_,i)=>106+i),...Array.from({length:103},(_,i)=>i).filter(i=>!(i>=61&&i<=80)&&![8,25,26,29,30,31,32,0,1,4,34,35,36,39].includes(i))]);
 controls('evolveControls',[P.evolve,P.amount,P.every]);controls('sequenceControls',[P.length,P.division,P.gate,31]);
 const globals=$('globals');globals.replaceChildren();for(const [i,name] of [[0,'Tempo'],[24,'Reverb model'],[8,'Reverb size'],[9,'Reverb damping'],[4,'Delay time'],[5,'Delay feedback']])control(globals,dev.gdescs[i],dev.g[i],v=>dev.global(i,v),name);
 $('read').disabled=!live;$('undo').disabled=!dev.undo?.after;$('grow').disabled=[10,13].includes(t.engine);$('applyMotif').disabled=[10,13].includes(t.engine);renderSteps();}
function presetOptions(selected=0){const en=Number($('engine').value);options($('preset'),data.ENG[en].presets.map(p=>p.name),selected);}
function renderSteps(){const t=dev.tracks[track];$('stepPage').textContent=`${page*16+1}–${page*16+16} / 64`;$('prev').disabled=page===0;$('next').disabled=page===3;$('grid').replaceChildren(...t.steps.slice(page*16,page*16+16).map((s,j)=>{const i=page*16+j,b=el('button',null,{className:`step ${s.time===0&&s.n?'active':''} ${i>=t.p[P.length]?'outside':''}`});b.setAttribute('aria-pressed',String(i===selectedStep));b.setAttribute('aria-label',`Step ${i+1}: ${s.time===2?'rest':s.time===1?'tie':s.notes.slice(0,s.n).map(noteName).join(' ')||'empty'}`);b.append(el('b',String(i+1).padStart(2,'0')),el('span',s.time===2?'·':s.time===1?'—':s.notes.slice(0,s.n).map(noteName).join(' ')||'·'));b.onclick=()=>{selectedStep=i;renderSteps();};return b;}));
 const s=t.steps[selectedStep],form=el('div',null,{className:'step-form'}),fields={};
 function field(key,title,type,value,min,max){const l=el('label',title),x=el('input',null,{type,value:String(value)});if(min!==undefined)x.min=String(min);if(max!==undefined)x.max=String(max);x.id='step-'+key;l.append(x);form.append(l);fields[key]=x;}
 const heading=el('h2',`Step ${selectedStep+1}`,{className:'full'});form.append(heading);field('notes','Notes / up to four','text',s.notes.slice(0,s.n).map(noteName).join(' '));
 const l=el('label','Event'),kind=el('select',null);options(kind,['Note','Tie','Rest'],s.time);l.append(kind);form.append(l);field('vel','Velocity','number',s.vel,0,127);field('chance','Chance %','number',s.chance,0,100);field('ratchet','Ratchet','number',s.ratchet,1,4);field('nudge','Nudge','number',s.nudge,-8,7);
 const row=el('div',null,{className:'full row'}),save=el('button','Apply step',{className:'primary'});save.onclick=()=>run(async()=>{const notes=parseNotes(fields.notes.value),steps=copy(dev.tracks[track].steps);steps[selectedStep]={...steps[selectedStep],n:notes.length,notes:[...notes,...Array(4-notes.length).fill(0)],time:Number(kind.value),vel:Number(fields.vel.value),chance:Number(fields.chance.value),ratchet:Number(fields.ratchet.value),nudge:Number(fields.nudge.value),condition:Number(fields.chance.value)!==s.chance?0:s.condition};await dev.writePhrase(track,steps);},live?'Step verified. Press PLAY on your FM-1.':'Step updated in the offline sketch.');row.append(save);form.append(row,el('p',`Step accents, slides, drum hits and condition ${s.condition} are preserved. Changing chance clears the condition.`,{className:'small full'}));$('stepEditor').replaceChildren(form);}
$('engine').onchange=()=>presetOptions();$('prev').onclick=()=>{page--;selectedStep=page*16;renderSteps();};$('next').onclick=()=>{page++;selectedStep=page*16;renderSteps();};
$('applySound').onclick=()=>{const k=track,i=Number($('sound').value);run(async()=>{await dev.sound(k,i);labels[k]=data.library.banks[k][i][0];},live?'Sound recipe applied and confirmed. Press PLAY on your FM-1.':'Sound recipe loaded in the silent sketch.');};
$('applyPreset').onclick=()=>{const k=track,e=Number($('engine').value),p=Number($('preset').value);run(async()=>{await dev.preset(k,e,p);labels[k]='';},live?'Factory sound loaded. Press PLAY on your FM-1.':'Factory sound loaded in the silent sketch.');};
$('grow').onclick=()=>{const k=track,opts={root:Number($('root').value),scale:Number($('scale').value),style:Number($('style').value),seed:Number($('seed').value)};run(async()=>{if(!Number.isInteger(opts.seed)||opts.seed<1||opts.seed>4294967295)throw Error('Seed must be 1…4294967295');await dev.stop();const before=await dev.readPhrase(k);const steps=grow(before,k,opts,data.scales);await dev.writePhrase(k,steps,{[P.root]:opts.root,[P.scale]:opts.scale,[P.quant]:3,[P.evolve]:0});$('seed').value=String((opts.seed+1)>>>0||1);},live?'New phrase verified and locked. Press PLAY on your FM-1.':'New phrase created and locked in the offline sketch.');};
$('applyMotif').onclick=()=>{const k=track,i=Number($('motif').value),density=Number($('density').value),root=Number($('root').value),scale=Number($('scale').value);run(async()=>{await dev.stop();const t=await dev.readPhrase(k);t.p[P.root]=root;t.p[P.scale]=scale;const steps=motif(t,k,data.library.motifs[i][1],density,data.scales[scale].mask);await dev.writePhrase(k,steps,{[P.root]:root,[P.scale]:scale,[P.quant]:3,[P.evolve]:0});},live?'Motif verified and locked. Press PLAY on your FM-1.':'Motif created in the offline sketch.');};
$('undo').onclick=()=>run(()=>dev.undoPhrase(),live?'Previous phrase restored. Press PLAY on your FM-1.':'Previous phrase restored.');
$('read').onclick=()=>run(async()=>{await dev.readTrack(track);labels[track]='';},'Track read from FM-1.');
function download(name,obj){const url=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}));const a=el('a',null,{href:url,download:name});a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('export').onclick=()=>run(async()=>{if(live)await dev.readTrack(track);download(`Bunker-${ROLE[track]}-phrase.json`,phraseFile(dev.tracks[track]));},'Phrase exported.');
$('recovery').onclick=()=>{if(recovery)download('Bunker-pre-edit-phrase.json',phraseFile(recovery));};
$('import').onchange=()=>{const file=$('import').files[0];if(!file)return;run(async()=>{if(file.size>100000)throw Error('Phrase file too large');const x=readPhrase(JSON.parse(await file.text()));if([10,13].includes(dev.tracks[track].engine))throw Error('Choose a pitched track for phrase import');await dev.writePhrase(track,x.steps,{[P.root]:x.root,[P.scale]:x.scale,[P.length]:x.length,[P.quant]:3,[P.evolve]:0});},live?'Imported phrase verified. Press PLAY on your FM-1.':'Phrase imported into the offline sketch.');};
$('find').onclick=()=>run(async()=>{midi=await ports();if(!midi.inputs.length||!midi.outputs.length)throw Error('No MIDI ports found. Connect your FM-1 with a data USB cable.');const list=ps=>ps.map(p=>({value:p.id,label:p.name||p.id}));const choose=ps=>ps.find(p=>/fm.?1|felucca|bunker/i.test(p.name))?.id||ps[0].id;options($('midiIn'),list(midi.inputs),choose(midi.inputs));options($('midiOut'),list(midi.outputs),choose(midi.outputs));},'Select the FM-1 input and output, then Connect & read.');
$('connect').onclick=()=>run(async()=>{const transport=await openMidi(midi.access,$('midiIn').value,$('midiOut').value);session=new Session(transport,{onFault:e=>{say(e.message,true);uiState();}});const candidate=new Device(session,data);try{await candidate.initialise();}catch(e){session.close(e);throw e;}dev=candidate;live=true;labels.fill('');track=0;},'FM-1 read successfully. Controls now edit the hardware.');
$('disconnect').onclick=()=>{session?.close();live=false;dev=null;uiState();say('Disconnected. Choose New offline sketch to continue locally.');};
$('offline').onclick=()=>run(async()=>{session?.close();session=null;live=false;dev=await new OfflineDevice(data).initialise();labels.fill('');track=page=selectedStep=0;},'Offline sketch ready. No hardware connected; no audio is generated here.');
window.addEventListener('pagehide',()=>session?.close());
try{const response=await fetch('./data.json');if(!response.ok)throw Error('Could not load the sound library');data=await response.json();dev=await new OfflineDevice(data).initialise();render();uiState();say('Offline sketch ready. Connect your FM-1 to edit and hear the real instrument.');}catch(e){say(e.message,true);}
